const F_DUPFD = 0;

const F_GETFD = 1;

const F_GETFL = 3;

const F_GETLK = 12;

const F_SETFD = 2;

const F_SETFL = 4;

const F_SETLK = 13;

const F_SETLKW = 14;

const F_UNLCK = 2;

